// Normaliza el lead venga como venga del formulario
const b = $json.body || $json;
const pick = (...k) => { for (const x of k){ if (b[x]) return String(b[x]).trim(); } return ''; };
const nombre = pick('nombre','name','first_name','fullname');
const email = pick('email','correo','mail').toLowerCase();
const telefono = pick('telefono','phone','whatsapp','celular');
if (!email && !telefono) { return []; } // lead basura sin contacto
const fecha = new Date().toISOString().slice(0,10);
return [{ json: { fecha, nombre, email, telefono } }];
